use vstd::prelude::*;

verus! {

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] == a[i],
{
    let mut result: Vec<T> = Vec::new();
    let mut i: usize = 0;

    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] == a[j],
        decreases a.len() - i,
    {
        // Read without modifying `a`, then push into the new vector.
        let x: T = a[i];
        result.push(x);
        i = i + 1;
    }

    result
}

} // verus!

